# Neutral sprite coordinates, measured directly against the 48x72 artwork.
# Left-side contours may be mirrored about x=23.5; all data resolves to pixels.
def mirror(p):return [(47-x,y) for x,y in p]
def shell(p):return p+mirror(p[::-1])
def spec(edge,glass=(),lamps=(),details=(),metal=()):
 return dict(body=[shell(edge)],protected=list(glass)+list(details),lamps=list(lamps),metal=list(metal))
def pair(p):return [p,mirror(p)]
